CREATE TABLE IF NOT EXISTS ad_ddl_default (tablename TEXT, columnname TEXT, defaultvalue TEXT);
INSERT INTO ad_ddl_default SELECT 'a_asset','a_asset_action','MD' WHERE NOT EXISTS (SELECT 1 FROM ad_ddl_default WHERE tablename='a_asset' AND columnname='a_asset_action');
INSERT INTO ad_ddl_default SELECT 'a_asset','a_asset_status','NW' WHERE NOT EXISTS (SELECT 1 FROM ad_ddl_default WHERE tablename='a_asset' AND columnname='a_asset_status');
