INSERT INTO ad_ddl_default SELECT 'a_asset','isdepreciated','Y' WHERE NOT EXISTS (SELECT 1 FROM ad_ddl_default WHERE tablename='a_asset' AND columnname='isdepreciated');
INSERT INTO ad_ddl_default SELECT 'a_asset','isdisposed','N' WHERE NOT EXISTS (SELECT 1 FROM ad_ddl_default WHERE tablename='a_asset' AND columnname='isdisposed');
INSERT INTO ad_ddl_default SELECT 'a_asset','isfullydepreciated','N' WHERE NOT EXISTS (SELECT 1 FROM ad_ddl_default WHERE tablename='a_asset' AND columnname='isfullydepreciated');
INSERT INTO ad_ddl_default SELECT 'a_asset','isinposession','Y' WHERE NOT EXISTS (SELECT 1 FROM ad_ddl_default WHERE tablename='a_asset' AND columnname='isinposession');
INSERT INTO ad_ddl_default SELECT 'a_asset','isowned','Y' WHERE NOT EXISTS (SELECT 1 FROM ad_ddl_default WHERE tablename='a_asset' AND columnname='isowned');
INSERT INTO ad_ddl_default SELECT 'a_asset','m_attributesetinstance_id','0' WHERE NOT EXISTS (SELECT 1 FROM ad_ddl_default WHERE tablename='a_asset' AND columnname='m_attributesetinstance_id');
INSERT INTO ad_ddl_default SELECT 'a_asset','processed','N' WHERE NOT EXISTS (SELECT 1 FROM ad_ddl_default WHERE tablename='a_asset' AND columnname='processed');
INSERT INTO ad_ddl_default SELECT 'a_asset','processing','N' WHERE NOT EXISTS (SELECT 1 FROM ad_ddl_default WHERE tablename='a_asset' AND columnname='processing');
INSERT INTO ad_ddl_default SELECT 'a_asset_group','isactive','Y' WHERE NOT EXISTS (SELECT 1 FROM ad_ddl_default WHERE tablename='a_asset_group' AND columnname='isactive');
INSERT INTO ad_ddl_default SELECT 'a_asset_group','iscreateasactive','Y' WHERE NOT EXISTS (SELECT 1 FROM ad_ddl_default WHERE tablename='a_asset_group' AND columnname='iscreateasactive');
