ct_id))) JOIN m_product mp ON ((ms.m_product_id = mp.m_product_id))) JOIN m_locator ml ON ((ms.m_locator_id = ml.m_locator_id))) LEFT JOIN m_locatortype lt ON ((ml.m_locatortype_id = lt.m_locatortype_id))) JOIN m_warehouse mw ON ((ml.m_warehouse_id = mw.m_warehouse_id))) JOIN m_productprice mpr ON ((ms.m_product_id = mpr.m_product_id))) JOIN m_pricelist_version mplv ON ((mplv.m_pricelist_version_id = mpr.m_pricelist_version_id))) JOIN m_pricelist mpl ON ((mplv.m_pricelist_id = mpl.m_pricelist_id))) JOIN ad_org org ON ((org.ad_org_id = mw.ad_org_id))) GROUP BY r.ad_client_id, r.ad_org_id, r.isactive, r.created, r.createdby, r.updated, r.updatedby, r.m_product_id, r.relatedproduct_id, mw.m_warehouse_id, mpr.m_pricelist_version_id, org.name, mp.name, mpl.c_currency_id;
