CREATE VIEW rv_c_invoiceline AS SELECT il.ad_client_id, il.ad_org_id, il.isactive, il.created, il.createdby, il.updated, il.updatedby, il.c_invoiceline_id, i.c_invoice_id, i.salesrep_id, i.c_bpartner_id, i.c_bp_group_id, il.m_product_id, p.m_product_category_id, i.dateinvoiced, i.dateacct, i.issotrx, i.c_doctype_id, i.docstatus, i.ispaid, il.c_campaign_id, il.c_project_id, il.c_activity_id, il.c_projectphase_id, il.c_projecttask_id, (il.qtyinvoiced * (i.multiplier)) AS qtyinvoiced, (il.qtyentered * (i.multiplier)) AS qtyentered, il.m_attributesetinstance_id, productattribute(il.m_attributesetinstance_id) AS productattribute, pasi.m_attributeset_id, pasi.m_lot_id, pasi.guaranteedate, pasi.lot, pasi.serno, il.pricelist, il.priceactual, il.pricelimit, il.priceentered, CASE WHEN (il.pricelist = (0)) THEN (0) ELSE currencyround((((il.pricelist - il.priceactual) * 1.0 / il.pricelist) * (100)), i.c_currency_id, 'N') END AS discount, CASE WHEN (il.pricelimit = (0)) THEN (0) ELSE currencyround((((il.priceactual - il.pricelimit) * 1.0 / il.pricelimit) * (100)), i.c_currency_id, 'N') END AS margin, CASE WHEN (il.pricelimit = (0)) THEN (0) ELSE (((il.priceactual - il.pricelimit) * il.qtyinvoiced) * (i.multiplier)) END AS marginamt, currencyround(((i.multiplier) * il.linenetamt), i.c_currency_id, 'N') AS linenetamt, currencyround((((i.multiplier) * il.pricelist) * il.qtyinvoiced), i.c_currency_id, 'N') AS linelistamt, CASE WHEN (COALESCE(il.pricelimit, (0)) = (0)) THEN currencyround(((i.multiplier) * il.linenetamt), i.c_currency_id, 'N') ELSE currencyround((((i.multiplier) * il.pricelimit) * il.qtyinvoiced), i.c_currency_id, 'N') END AS linelimitamt, currencyround(((i.multiplier) * ((il.pricelist * il.qtyinvoiced) - il.linenetamt)), i.c_currency_id, 'N') AS linediscountamt, CASE WHEN (COALESCE(il.pricelimit, (0)) = (0)) THEN (0) ELSE currencyround(((i.multiplier) * (il.linenetamt - (il.pricelimit * il.qtyinvoiced))), i.c_currency_id, 'N') END AS lineoverlimitamt, il.ad_orgtrx_id, il.a_processed, il.c_charge_id, il.c_orderline_id, il.c_tax_id, il.c_uom_id AS c_invoiceline_c_uom_id, il.description AS c_invoiceline_description, il.isdescription, il.isprinted, il.line, il.linenetamt AS c_invoiceline_linenetamt, il.linetotalamt, il.m_inoutline_id, il.m_rmaline_id, il.processed, il.ref_invoiceline_id, il.rramt, il.rrstartdate, il.s_resourceassignment_id, il.taxamt, il.user1_id, il.user2_id, p.ad_org_id AS m_product_ad_org_id, p.classification, p.copyfrom AS m_product_copyfrom, p.created AS m_product_created, p.createdby AS m_product_createdby, p.c_revenuerecognition_id, p.c_subscriptiontype_id, p.c_taxcategory_id, p.c_uom_id AS m_productline_c_uom_id, p.description AS m_product_description, p.descriptionurl, p.discontinued, p.discontinuedat, p.documentnote, p.group1, p.group2, p.guaranteedays, p.guaranteedaysmin, p.help, p.imageurl, p.isactive AS m_product_isactive, p.isdropship, p.isexcludeautodelivery, p.isinvoiceprintdetails, p.ispicklistprintdetails, p.ispurchased, p.isselfservice, p.issold, p.isstocked, p.issummary AS m_product_issummary, p.isverified, p.iswebstorefeatured, p.lowlevel, p.m_attributeset_id AS m_product_m_attributeset_id, p.m_freightcategory_id, p.m_locator_id, p.m_product_id AS m_product_m_product_id, p.processing AS m_product_processing, p.producttype, p.r_mailtext_id, p.salesrep_id AS m_product_salesrep_id, p.s_expensetype_id, p.shelfdepth, p.shelfheight, p.shelfwidth, p.sku, p.s_resource_id, p.unitsperpack, p.unitsperpallet, p.updated AS m_product_updated, p.updatedby AS m_product_updatedby, p.versionno, p.volume, p.weight, pasi.ad_org_id AS m_asi_ad_org_id, pasi.created AS m_attributesetinstance_created, pasi.createdby AS m_asi_createdby, pasi.description AS m_asi_description, pasi.isactive AS m_attributesetinstance_isacti, pasi.serno AS m_attributesetinstance_serno, pasi.updated AS m_attributesetinstance_updated, pasi.updatedby AS m_asi_updatedby, pc.m_product_category_parent_id FROM ((((rv_c_invoice i JOIN c_invoiceline il ON ((i.c_invoice_id = il.c_invoice_id))) LEFT JOIN m_product p ON ((il.m_product_id = p.m_product_id))) LEFT JOIN m_product_category pc ON ((p.m_product_category_id = pc.m_product_category_id))) LEFT JOIN m_attributesetinstance pasi ON ((il.m_attributesetinstance_id = pasi.m_attributesetinstance_id)));
DROP VIEW IF EXISTS fact_acct_balance;
CREATE VIEW fact_acct_balance AS SELECT a.ad_client_id, a.ad_org_id, a.c_acctschema_id, trunc(a.dateacct) AS dateacct, a.account_id, a.postingtype, a.m_product_id, a.c_bpartner_id, a.c_project_id, a.ad_orgtrx_id, a.c_salesregion_id, a.c_activity_id, a.c_campaign_id, a.c_locto_id, a.c_locfrom_id, a.user1_id, a.user2_id, a.gl_budget_id, COALESCE(sum(a.amtacctdr), (0)) AS amtacctdr, COALESCE(sum(a.amtacctcr), (0)) AS amtacctcr, COALESCE(sum(a.qty), (0)) AS qty, max(a.createdby) AS createdby, max(a.created) AS created, max(a.updatedby) AS updatedby, max(a.updated) AS updated, max(a.isactive) AS isactive, max(a.c_subacct_id) AS c_subacct_id, a.userelement1_id, a.userelement2_id, max(a.c_projectphase_id) AS c_projectphase_id, max(a.c_projecttask_id) AS c_projecttask_id FROM fact_acct a GROUP BY a.ad_client_id, a.ad_org_id, a.c_acctschema_id, (trunc(a.dateacct)), a.account_id, a.postingtype, a.m_product_id, a.c_bpartner_id, a.c_project_id, a.ad_orgtrx_id, a.c_salesregion_id, a.c_activity_id, a.c_campaign_id, a.c_locto_id, a.c_locfrom_id, a.user1_id, a.user2_id, a.userelement1_id, a.userelement2_id, a.gl_budget_id;
