d_org_id, u.isactive, r.created, r.createdby, r.updated, r.updatedby, r.r_request_id, u.ad_user_id, NULL AS isselfservice, NULL AS r_group_id, NULL AS r_requesttype_id, NULL AS r_category_id FROM (r_request r JOIN ad_user_roles u ON ((u.ad_role_id = r.ad_role_id)));
