CREATE VIEW ad_allroles_v AS SELECT 0 AS ad_client_id, 0 AS ad_org_id, ad_role.ad_role_id AS ad_allroles_v_id, ad_role.ad_role_uu AS ad_allroles_v_uu, ad_role.created, ad_role.createdby, ad_role.updated, ad_role.updatedby, ad_role.isactive, ad_role.name, ad_role.description, ad_role.userlevel, ad_role.ismanual, ad_role.isshowacct, ad_role.ispersonallock, ad_role.ispersonalaccess, ad_role.iscanexport, ad_role.iscanreport, ad_role.isaccessallorgs, ad_role.ischangelog, ad_role.preferencetype, ad_role.isuseuserorgaccess, ad_role.ismasterrole, ad_role.isaccessadvanced, ad_role.roletype, ad_role.ad_client_id AS ad_allclients_v_id FROM ad_role;
DROP VIEW IF EXISTS ad_alluserroles_v;
CREATE VIEW ad_alluserroles_v AS SELECT 0 AS ad_client_id, 0 AS ad_org_id, ad_user_roles.ad_user_id AS ad_allusers_v_id, ad_role.ad_client_id AS ad_allclients_v_id, CASE WHEN (ad_user_roles.isactive = 'N') THEN ad_user_roles.isactive ELSE ad_role.isactive END AS isactive, ad_user_roles.created, ad_user_roles.createdby, ad_user_roles.updated, ad_user_roles.updatedby, ad_user_roles.ad_user_roles_uu AS ad_alluserroles_v_uu, ad_role.name, ad_role.description, ad_role.userlevel, ad_role.ismanual, ad_role.isshowacct, ad_role.ispersonallock, ad_role.ispersonalaccess, ad_role.iscanexport, ad_role.iscanreport, ad_role.isaccessallorgs, ad_role.ischangelog, ad_role.preferencetype, ad_role.isuseuserorgaccess, ad_role.ismasterrole, ad_role.isaccessadvanced, ad_role.roletype, ad_role.ad_role_id AS ad_allroles_v_id FROM (ad_user_roles JOIN ad_role ON ((ad_role.ad_role_id = ad_user_roles.ad_role_id)));
DROP VIEW IF EXISTS ad_allclients_v;
CREATE VIEW ad_allclients_v AS SELECT 0 AS ad_client_id, 0 AS ad_org_id, ad_client.ad_client_id AS ad_allclients_v_id, ad_client.isactive, ad_client.created, ad_client.createdby, ad_client.updated, ad_client.updatedby, ad_client.value, ad_client.name, ad_client.description, ad_client.ad_language, ad_client.ad_client_uu AS ad_allclients_v_uu FROM ad_client;
DROP VIEW IF EXISTS ad_sessioninfo_v;
CREATE VIEW ad_sessioninfo_v AS SELECT 0 AS ad_client_id, 0 AS ad_org_id, s.isactive, s.created, s.createdby, s.updated, s.updatedby, substr((s.websession), 1, 40) AS websession, substr((s.remote_addr), 1, 60) AS remote_addr, substr((s.remote_host), 1, 120) AS remote_host, substr((r.name), 1, 60) AS rolename, s.logindate, s.ad_session_uu, substr((s.servername), 1, 80) AS servername, substr((c.name), 1, 60) AS clientname, substr((o.name), 1, 60) AS orgname, s.ad_session_id AS ad_sessioninfo_v_id, s.ad_session_uu AS ad_sessioninfo_v_uu, substr((u.name), 1, 60) AS loginname, substr((u.email), 1, 60) AS email, substr((u.ldapuser), 1, 60) AS ldapuser, substr((s.description), 1, 2000) AS description, s.ad_session_id FROM ((((ad_session s JOIN ad_user u ON ((s.createdby = u.ad_user_id))) LEFT JOIN ad_role r ON ((s.ad_role_id = r.ad_role_id))) JOIN ad_client c ON ((s.ad_client_id = c.ad_client_id))) LEFT JOIN ad_org o ON ((s.ad_org_id = o.ad_org_id))) WHERE (s.processed = 'N');
